"""Literal diagnostic report; no posthoc gate substitution."""
from common import *
def render(r,handoff,replay,preservation):
 lines=[];arms=r['arms'];decision=r['decision'];comp=r['paired_comparisons'];mechanism=r['prediction_mechanism']
 def add(s=''):lines.append(s)
 def table(headers,rows):
  add('| '+' | '.join(headers)+' |');add('| '+' | '.join(['---']*len(headers))+' |')
  for row in rows:add('| '+' | '.join(map(str,row))+' |')
  add()
 add('# Horus Delta Prediction Pilot v0');add();add('**'+decision['classification']+'**. '+('Recommend a separately authorized confirmatory proposal for '+decision['recommended_arm']+'.' if decision['recommend_scale_up'] else 'Do not scale this intervention from this pilot.'));add()
 add('All 544 scientific responses completed: 16 fresh matched worlds, six discovery probes and two shared sealed predictions per B/D/T arm, plus 160 fresh analyses before D/T decisions 2–6. The prior NEITHER_INTERVENTION_CONFIRMED result remains unchanged. No training, integration, merge or automatic follow-up.');add()
 add('B is grounded bookkeeping. D compares executed evidence, describes a provisional relation and predicts an untested case. T applies Time/Relation/Direction to that relation and extrapolation, including an explicit alternative outcome. Each fresh analysis enters only its own independent legal selector. Previous prose, proposals and receipt scores never enter later model contexts. INSUFFICIENT_DELTA is legitimate.');add()
 add('## Provenance');add();table(['Artifact','Identity'],[(k,'`'+str(v)+'`') for k,v in handoff.items()]);add('The containing commit identifies the report; exact remote publication is verified in the private publication receipt.');add()
 add('## Matched outcomes');add();table(['Arm','Repeats /96','Zero-info /96','Unique probes','Mean information bits','Median final H','Median log2 H','Useful contrasts','Sealed exact /32','Sealed bit accuracy','Mean rank','Mean regret'],[(a,z['exact_repeats'],z['zero_information'],z['unique_probe_sequences'],round(z['mean_information_bits'],4),z['median_final_H'],round(z['median_final_log2_H'],4),z['useful_controlled_contrasts'],z['prediction']['exact'],round(z['prediction']['bit_accuracy'],4),round(z['mean_selected_rank'],3),round(z['mean_regret_bits'],4)) for a,z in arms.items()])
 table(['Arm','Calls','Prompt tokens','Generated tokens','Inference seconds'],[(a,c['model_calls'],c['prompt_tokens'],c['generation_token_count'],round(c['seconds'],2)) for a,c in r['costs'].items()])
 add('## Learning curves');add();table(['Arm','Probe','Median log2 H','Mean cumulative bits','Repeats','Zero-info','Useful contrasts'],[(a,t,round(z['curves'][str(t)]['median_log2_H'],4),round(z['curves'][str(t)]['mean_cumulative_bits'],4),z['curves'][str(t)]['exact_repeats'],z['curves'][str(t)]['zero_information'],z['curves'][str(t)]['useful_contrasts']) for a,z in arms.items() for t in [1,2,3,4,6]])
 add('## Paired screening');add();table(['Comparison','Median paired bits','Mean bits/probe advantage','Wins/ties/losses','Useful contrast advantage/world','Zero-info reduction','Sealed exact difference','Sealed bit difference'],[(n,round(c['median_paired_information_advantage_bits'],4),round(c['mean_information_per_probe_advantage'],4),str(c['information_wins'])+'/'+str(c['information_ties'])+'/'+str(c['information_losses']),c['useful_contrast_mean_advantage'],c['zero_information_reduction'],c['short_exact_difference'],c['short_bit_accuracy_difference']) for n,c in comp.items()])
 for n,z in decision['screening'].items():add('- '+n+': '+('PASS' if z['passed'] else 'FAIL: '+', '.join(k for k,v in z['conditions'].items() if not v)))
 z=decision['triangulation_increment'];add('- T-D additional benefit: '+('PASS' if z['passed'] else 'FAIL: '+', '.join(k for k,v in z['conditions'].items() if not v)));add()
 add('Every condition is mandatory. No formal competence or significance claim is made. All sixteen paired differences are available in results.json. T is recommended only if T-B and T-D both pass; otherwise D is preferred if D-B passes. Neither a conceptual preference nor one favorable metric can replace the gate.');add()
 add('## Prediction receipts and evidence fidelity');add()
 keys=sorted(set().union(*(m['counts'] for m in mechanism.values())));table(['Count','D','T'],[(k,mechanism['D']['counts'].get(k,0),mechanism['T']['counts'].get(k,0)) for k in keys])
 table(['Arm','Exact accuracy among tested','Bit accuracy among tested','Fraction selecting current prediction','Mean bits testing prediction','Mean bits ignoring a valid prediction','Mean paired B advantage on prediction-testing steps','Worlds testing predictions'],[(a,m['accuracy_among_tested'],m['bit_accuracy_among_tested'],m['selected_current_prediction_fraction'],m['mean_information_testing_prediction'],m['mean_information_not_testing_prediction'],m['mean_matched_baseline_information_advantage_when_testing'],m['prediction_testing_worlds']) for a,m in mechanism.items()])
 add('Supported means all predicted bits matched; contradicted means none matched; partially matched means some but not all matched. Any-bit contradiction includes partial matches and is reported separately. Never-tested proposals receive no correctness credit. Only actual later execution of the exact predicted probe ID scores a receipt. T discrimination requires the executed full trace to match exactly one of two distinct forecasts. An outcome matching neither does not force a winner.');add()
 add('Evidence fidelity checks validate referenced executions, copied endpoints and input-comparison labels. They do not certify causal prose. Prediction-testing versus ignoring comparisons and later changes after contradiction are descriptive, with different selected cases and correlated receipts. The screening benchmark compares prediction-testing choices with B choices at the same world/step. B choices do not carry model predictions.');add()
 add('## Integrity and limitations');add();add('Complete raw evidence was committed before scoring. Authentication, ordered non-authoritative receipts, exact prompt/ledger reconstruction, public-only grammar validation, legal choices and sealing passed zero-inference replay. Two scoring passes were byte-identical.');add();add('Audits: `'+canon(r['audits'])+'`. Replay: `'+canon(replay)+'`. Preservation: `'+canon(preservation)+'`.');add()
 add('The analysis grammar constrains only public references, JSON structure, trace dimensions, bounded ASCII prose and distinct alternatives. Every substantive choice and predicted bit remains model-generated. No hidden H, program list, best probe, utility or unexecuted world output enters the worker. D/T use extra inference versus B; T also uses a different prompt and explicit alternative forecast versus D. Results apply to these bundles. Fixed sensors/actions and finite machines do not establish unrestricted open-world inquiry.');add()
 add('## Ten requested answers');add()
 answers=[('Did comparing observations before selecting an experiment improve inquiry?','The D-B and T-B screening outcomes above govern the answer. Median paired information advantages are '+str(comp['D-B']['median_paired_information_advantage_bits'])+' and '+str(comp['T-B']['median_paired_information_advantage_bits'])+' bits respectively.'),('Were meaningful deltas identified rather than unsupported relations invented?','Copied-endpoint accuracy, input-label validity and valid controlled endpoint differences are counted above. Those establish limited grounding; the causal relation prose itself is not certified.'),('Did evidence-grounded relations produce testable predictions?','D generated '+str(mechanism['D']['counts'].get('predictions_generated',0))+' valid predictions and T generated '+str(mechanism['T']['counts'].get('predictions_generated',0))+'. Their exact forecast and eventual-execution counts distinguish testability from correctness.'),('Did prediction-testing experiments gain more information?','Both within-arm testing/ignoring means and matched B comparisons are reported above. Empty groups remain unmeasured; associations are not causal proof that the prose improved the choice.'),('Did contradictions lead to different subsequent behavior?','The receipt counts report subsequent target/trace changes and selected-probe changes after any-bit contradiction. Previous proposals were not supplied again. These are observed changes, not proof of causal adaptation or effective falsification.'),('Did D outperform bookkeeping B?',str(decision['screening']['D-B']['passed'])+' under the complete frozen screening gate.'),('Did prediction-stage Triangulation improve over D?',str(decision['triangulation_increment']['passed'])+' under the separate T-D gate. Conceptual richness receives no credit.'),('Did either method improve sealed prediction?','D-B exact/bit differences: '+str(comp['D-B']['short_exact_difference'])+'/'+str(comp['D-B']['short_bit_accuracy_difference'])+'; T-B: '+str(comp['T-B']['short_exact_difference'])+'/'+str(comp['T-B']['short_bit_accuracy_difference'])+'. Only 32 endpoints per arm; no powered prediction noninferiority claim.'),('Did the mechanism operate without a complete hypothesis map?','No finite hypothesis catalogue or oracle value was model-visible. Whether the intervention helped is determined by the gates, and this fixed-action simulator still does not establish general open-world capability.'),('Which piece deserves a larger confirmatory test?',decision['recommended_arm']+' under the frozen rule; separate authorization required.' if decision['recommended_arm'] else 'Neither qualifies. The placement hypothesis is unsupported by this screening gate; stop.')]
 for i,(question,answer) in enumerate(answers,1):add(f'{i}. **{question}** {answer}');add()
 add('STOP. No training, architecture integration, merge or automatic follow-up.')
 return '\n'.join(lines)+'\n'
